import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { SocialIcon } from 'react-social-icons';
import Chord from '@tombatossals/react-chords/lib/Chord';
import Accordion from './Accordion';
import TunerButton from './TunerButton';
import './styles.css';

// Define the chords as constants with explicit types
const E_CHORD = {
  frets: [0, 2, 2, 1, 0, 0] as number[],
  fingers: [0, 2, 3, 1, 0, 0] as number[],
  barres: [] as number[],
  capo: false as boolean
};

const G_CHORD = {
  frets: [3, 2, 0, 0, 0, 1] as number[],
  fingers: [3, 2, 0, 0, 0, 1] as number[],
  barres: [] as number[],
  capo: false as boolean
};

const C_CHORD = {
  frets: [0, 3, 2, 0, 1, 0] as number[],
  fingers: [0, 3, 2, 0, 1, 0] as number[],
  barres: [] as number[],
  capo: false as boolean
};

const F_CHORD = {
  frets: [1, 3, 3, 2, 1, 1] as number[],
  fingers: [1, 3, 4, 2, 1, 1] as number[],
  barres: [1] as number[],
  capo: false as boolean
};

const D_CHORD = {
  frets: [0, 0, 0, 2, 3, 1] as number[],
  fingers: [0, 0, 0, 2, 3, 1] as number[],
  barres: [] as number[],
  capo: false as boolean
};

// Fixed the return type issue by explicitly returning JSX.Element
const MyChord = ({ chordArr }: { chordArr: typeof E_CHORD }): JSX.Element => {
  const instrument = {
    strings: 6,
    fretsOnChord: 4,
    name: 'Guitar',
    keys: [],
    tunings: {
      standard: ['E', 'A', 'D', 'G', 'B', 'E'],
    },
  };
  
  try {
    return <Chord chord={chordArr} instrument={instrument} lite={false} />;
  } catch (e) {
    return <Chord chord={E_CHORD} instrument={instrument} lite={false} />;
  }
};

function calculateData(number: number): typeof E_CHORD {
  const chords = [E_CHORD, G_CHORD, C_CHORD, F_CHORD, D_CHORD];
  return chords[number] || D_CHORD;
}

function App() {
  const [chordState, setChordState] = useState<typeof E_CHORD>(E_CHORD);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const timer = setInterval(() => {
      setChordState(calculateData(Math.floor(Math.random() * 5)));
    }, 1500);

    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    
    return () => {
      clearInterval(timer);
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  return (
    <div className="min-h-screen">
      <nav className={`navbar ${isScrolled ? 'scrolled' : ''}`}>
        <div className="logo">JW</div>
        <div className="nav-links">
          {/* Navigation links can be added here */}
        </div>
      </nav>

      <main className="hero">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center"
        >
          <div className="chord-diagram">
            <MyChord chordArr={chordState} />
          </div>

          <motion.h1 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2 }}
            className="text-center"
          >
            John Williams
          </motion.h1>
          
          <motion.p 
            className="subtitle"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3 }}
          >
            Private Guitar Teacher in San Diego
          </motion.p>

          <div className="cta-container">
            <button
              onClick={() => setIsModalOpen(true)}
              className="cta-button secondary-cta"
            >
              <i className="fas fa-info-circle"></i>
              Learn More
            </button>

            <a 
              href="https://0kgjda4nd6j.typeform.com/to/xAozLYBb"
              className="cta-button primary-cta"
              target="_blank"
              rel="noopener noreferrer"
            >
              <i className="fas fa-calendar-alt"></i>
              Book your <span className="font-bold">FREE</span> Lesson
            </a>

            <TunerButton 
              href="https://johnjaguar.github.io/Tuner/"
              onClick={() => {
                console.log('Tuner button clicked');
              }} 
            />
          </div>

          <div className="social-links">
            <SocialIcon url="mailto:jaydubthedub@gmail.com" />
            <SocialIcon 
              url="https://www.linkedin.com/in/john-williams-672301235/" 
              target="_blank" 
            />
            <SocialIcon 
              url="https://www.youtube.com/watch?v=FMP-0Nfe-9k" 
              target="_blank" 
            />
            <SocialIcon 
              url="https://www.instagram.com/guitarlessons.fun" 
              target="_blank" 
            />
            <SocialIcon 
              url="https://www.yelp.com/biz/john-williams-san-diego" 
              target="_blank" 
            />
          </div>
        </motion.div>

        {/* Custom Modal instead of react-modal */}
        {isModalOpen && (
          <div 
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: 'rgba(0, 0, 0, 0.75)',
              zIndex: 9999,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: '20px'
            }}
            onClick={(e) => {
              if (e.target === e.currentTarget) {
                setIsModalOpen(false);
              }
            }}
          >
            <div 
              style={{
                background: 'white',
                borderRadius: '12px',
                maxWidth: '90%',
                maxHeight: '90vh',
                overflow: 'auto',
                outline: 'none',
                boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)',
                position: 'relative'
              }}
            >
              <div 
                className="modal-header" 
                style={{
                  position: 'relative',
                  padding: '24px 24px 16px 24px',
                  borderBottom: '1px solid #e5e7eb',
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  borderRadius: '12px 12px 0 0'
                }}
              >
                <h2 
                  className="text-2xl font-bold mb-4" 
                  style={{ margin: 0, color: 'white' }}
                >
                  About Guitar Lessons
                </h2>
                <button 
                  onClick={() => {
                    console.log('Modal close button clicked');
                    setIsModalOpen(false);
                  }}
                  className="absolute top-4 right-4 text-gray-600 hover:text-gray-800"
                  style={{
                    background: 'none',
                    border: 'none',
                    color: 'white',
                    fontSize: '24px',
                    cursor: 'pointer',
                    padding: '4px',
                    borderRadius: '4px',
                    position: 'absolute',
                    top: '16px',
                    right: '16px'
                  }}
                >
                  ✕
                </button>
              </div>
              <div style={{ padding: '24px', background: 'white' }}>
                <Accordion />
              </div>
            </div>
          </div>
        )}

        <div className="scroll-indicator">
          <i className="fas fa-chevron-down"></i>
        </div>
      </main>
    </div>
  );
}

export default App;
